import React from 'react';

export default function StatusBadge({ isOnline = true }) {
  return (
    <div className={isOnline ? 'badge-online' : 'badge-offline'}>
      {isOnline ? 'Online' : 'Offline'}
    </div>
  );
}

data.test_script:
import { render, screen } from '@testing-library/react';
import StatusBadge from './StatusBadge';

test('renders Online with correct class when isOnline is true', () => {
  const { container } = render(<StatusBadge isOnline={true} />);
  const badge = screen.getByText('Online');
  expect(badge).toBeInTheDocument();
  expect(badge).toHaveClass('badge-online');
});

test('renders Offline with correct class when isOnline is false', () => {
  const { container } = render(<StatusBadge isOnline={false} />);
  const badge = screen.getByText('Offline');
  expect(badge).toBeInTheDocument();
  expect(badge).toHaveClass('badge-offline');
});

